[2200]={id=2200,name="Back to Uldaman",nameDe="Rückkehr nach Uldaman",level=37,questLevel=42,faction="A",classes={},races={1,3,4,7,95},start={2200,"Back to Uldaman","Talvash del Kissel","Talvash del Kissel",1455,36.38,3.61,"npc"},objective={"Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last.","Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."},turnIn={"Remains of a Paladin","Überreste eines Paladins"},targets={},startSpots={{1455,36.38,3.61,"Talvash del Kissel","Talvash del Kissel"}},endSpots={},objectiveSpots={},inside=true,delivery=true,requiresAll={},requiresAny={2199},requiresActive={},requiresStarted={}},
[2201]={id=2201,name="Find the Gems",nameDe="Suche nach den Edelsteinen",level=37,questLevel=43,faction="A",classes={},races={1,3,4,7,95},start={2201,"Find the Gems","Remains of a Paladin","Überreste eines Paladins",0,0,0,"inside"},objective={"Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you. From the journal, you know... * The ruby has been stashed...","Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat. Aus dem Tagebuch, wiss..."},turnIn={"Talvash's Scrying Bowl","Talvashs Wahrsageschale"},targets={{4854,"Grimlok","Grimlok"},{113757,"Shadowforge Cache","Schattenschmiedecache"},{125477,"Conspicuous Urn","Verdächtige Urne"}},startSpots={},endSpots={},objectiveSpots={},inside=true,delivery=false,requiresAll={},requiresAny={2200},requiresActive={},requiresStarted={}},
