[5382]={id=5382,name="Doctor Theolen Krastinov, the Butcher",nameDe="Doktor Theolen Krastinov, der Schlächter",level=55,questLevel=60,classes={},races={},start={5382,"Doctor Theolen Krastinov, the Butcher","Eva Sarkhoff","Eva Sarkhoff",1422,70.22,73.71,"npc"},objective={"Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.","Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt."},turnIn={"Eva Sarkhoff","Eva Sarkhoff"},targets={{11261,"Doctor Theolen Krastinov","Doktor Theolen Krastinov"},{176544,"Remains of Eva Sarkhoff","Überreste von Eva Sarkhoff"},{176545,"Remains of Lucien Sarkhoff","Überreste von Lucien Sarkhoff"}},startSpots={{1422,70.22,73.71,"Eva Sarkhoff","Eva Sarkhoff"}},endSpots={{1422,70.22,73.71,"Eva Sarkhoff","Eva Sarkhoff"}},objectiveSpots={},inside=true,delivery=false,requiresAll={},requiresAny={},requiresActive={},requiresStarted={}},
[5384]={id=5384,name="Kirtonos the Herald",nameDe="Kirtonos der Herold",level=55,questLevel=60,classes={},races={},start={5384,"Kirtonos the Herald","Eva Sarkhoff","Eva Sarkhoff",1422,70.22,73.71,"npc"},objective={"Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva S...","Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren. Kämpft tapfer, gebt keinen Fußbreit nach! Vernicht..."},turnIn={"Eva Sarkhoff","Eva Sarkhoff"},targets={{10506,"Kirtonos the Herald","Kirtonos der Herold"}},startSpots={{1422,70.22,73.71,"Eva Sarkhoff","Eva Sarkhoff"}},endSpots={{1422,70.22,73.71,"Eva Sarkhoff","Eva Sarkhoff"}},objectiveSpots={},inside=true,delivery=false,requiresAll={},requiresAny={5515},requiresActive={},requiresStarted={}},
