[6133]={id=6133,name="The Ranger Lord's Behest",nameDe="Das Ersuchen des Waldläuferlords",level=54,questLevel=60,faction="H",classes={},races={2,5,6,8,96},start={6133,"The Ranger Lord's Behest","Nathanos Blightcaller","Nathanos Blightcaller",1423,22.23,63.51,"npc"},objective={"Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge. You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.","Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge. Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbei..."},turnIn={"Nathanos Blightcaller","Nathanos Blightcaller"},targets={{8563,"Woodsman","Waldmann"},{8564,"Ranger","Waldläufer"},{8565,"Pathstrider","Pfadschreiter"},{177747,"Quel'Thalas Registry","Quel’Thalas-Registratur"}},startSpots={{1423,22.23,63.51,"Nathanos Blightcaller","Nathanos Blightcaller"}},endSpots={{1423,22.23,63.51,"Nathanos Blightcaller","Nathanos Blightcaller"}},objectiveSpots={{1423,44.68,12.55,"Ranger","Waldläufer"},{1423,45.27,12.7,"Quel'Thalas Registry","Quel’Thalas-Registratur"},{1423,46.69,13.18,"Pathstrider","Pfadschreiter"},{1423,46.93,13.19,"Woodsman","Waldmann"}},inside=false,delivery=false,requiresAll={},requiresAny={},requiresActive={},requiresStarted={}},
