[7647]={id=7647,name="Judgment and Redemption",nameDe="Gerechtigkeit und Erlösung",level=60,questLevel=60,faction="A",classes={2},races={1,3},start={7647,"Judgment and Redemption","Lord Grayson Shadowbreaker","Lord Grayson Shadowbreaker",1453,48.43,50.22,"npc"},objective={"Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim th...","Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das besiegen der Geister wird der Todesritter Schat..."},turnIn={"Darkreaver's Fallen Charger","Schattensichels gefallenes Streitross"},targets={{10488,"Risen Construct","Auferstandenes Konstrukt"},{11458,"Petrified Treant","Versteinerter Treant"}},startSpots={{1453,48.43,50.22,"Lord Grayson Shadowbreaker","Lord Grayson Shadowbreaker"}},endSpots={},objectiveSpots={},inside=true,delivery=false,requiresAll={},requiresAny={7646},requiresActive={},requiresStarted={}},
