[8257]={id=8257,name="Blood of Morphaz",nameDe="Morphaz' Blut",level=50,questLevel=52,classes={5},races={},start={8257,"Blood of Morphaz","Ogtinc","Ogtinc",1447,42.4,42.62,"npc"},objective={"Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.","Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends."},turnIn={"Greta Mosshoof","Greta Mosshoof"},targets={{5719,"Morphaz","Morphaz"}},startSpots={{1447,42.4,42.62,"Ogtinc","Ogtinc"}},endSpots={{1448,51.21,82.11,"Greta Mosshoof","Greta Mosshoof"}},objectiveSpots={},inside=true,delivery=false,requiresAll={},requiresAny={8256},requiresActive={},requiresStarted={}},
[8258]={id=8258,name="The Darkreaver Menace",nameDe="Die Bedrohung durch Schattensichel",level=60,questLevel=60,faction="H",classes={7},races={2,5,6,8,96},start={8258,"The Darkreaver Menace","Sagorne Creststrider","Sagorne Creststrider",1454,38.66,35.92,"npc"},objective={"Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him. Bring Darkreaver'...","Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel aufta..."},turnIn={"Sagorne Creststrider","Sagorne Creststrider"},targets={{14516,"Death Knight Darkreaver","Todesritter Schattensichel"}},startSpots={{1454,38.66,35.92,"Sagorne Creststrider","Sagorne Creststrider"}},endSpots={{1454,38.66,35.92,"Sagorne Creststrider","Sagorne Creststrider"}},objectiveSpots={},inside=true,delivery=false,requiresAll={},requiresAny={7667},requiresActive={},requiresStarted={}},
